{
  "$schema": "https://opencode.ai/config.json",
  "model": "opencode/deepseek-v4-flash-free",
  "default_agent": "jarvis",
  "share": "disabled",
  "instructions": [
    "~/.config/opencode/global-rules.md",
    "~/.config/opencode/persona/soul.md"
  ],
  "permission": {
    "bash": {
      "*find*": "deny",
      "*grep*": "deny",
      "*npm*": "deny",
      "*sqlite*": "ask",
      "*opencode*": "ask"
    },
    "glob": "deny",
    "grep": "deny",
    "websearch": "deny"
  },
  "mcp": {
    "exa": {
      "type": "remote",
      "url": "http://127.0.0.1:18099",
      "enabled": true,
      "timeout": 120000
    },
    "deepwiki": {
      "type": "remote",
      "url": "https://mcp.deepwiki.com/mcp",
      "enabled": true,
      "timeout": 120000
    },
    "sequential-thinking": {
      "type": "local",
      "command": [
        "/home/kasiro/.bun/bin/mcp-server-sequential-thinking"
      ],
      "timeout": 120000,
      "enabled": true
    },
    "context7": {
      "type": "remote",
      "url": "https://mcp.context7.com/mcp",
      "enabled": true,
      "timeout": 120000,
      "headers": {
        "Authorization": "Bearer ctx7sk-418a5f6a-2b9c-4caa-94e2-573821193500"
      }
    },
    "web-research": {
      "type": "local",
      "command": [
        "web-research-mcp"
      ],
      "enabled": true,
      "timeout": 60000,
      "description": "\u041f\u043e\u0438\u0441\u043a \u0447\u0435\u0440\u0435\u0437 DuckDuckGo + fetch \u0441\u0442\u0440\u0430\u043d\u0438\u0446"
    },
    "searxng": {
      "type": "local",
      "command": [
        "mcp-searxng"
      ],
      "enabled": true,
      "timeout": 60000,
      "environment": {
        "SEARXNG_URL": "http://localhost:8099",
        "SEARXNG_MAX_RESULTS": "15"
      },
      "description": "\u041f\u043e\u0438\u0441\u043a \u0447\u0435\u0440\u0435\u0437 \u0441\u0432\u043e\u0439 SearXNG (Docker) + web_url_read"
    },
    "crawl4ai": {
      "type": "local",
      "command": [
        "/home/kasiro/\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b/python_projects/crawl4ai-mcp/.venv/bin/python",
        "-m",
        "crawl4ai_mcp.server"
      ],
      "timeout": 60000,
      "enabled": true,
      "description": "Crawl4AI MCP \u2014 \u043a\u0440\u0430\u0443\u043b\u0438\u043d\u0433, \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0445, sitemap, browser sessions"
    },
    "youtube-transcript": {
      "type": "local",
      "command": [
        "/home/kasiro/\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b/python_projects/yt-transcript-mcp/.venv/bin/yt-transcript-mcp"
      ],
      "environment": {
        "EXA_API_KEY": "57c7932c-0ffa-4f75-8173-da5b8a343752"
      },
      "timeout": 60000,
      "enabled": true
    },
    "chrome-devtools": {
      "type": "local",
      "command": [
        "/home/kasiro/.bun/bin/chrome-devtools-mcp",
        "--executablePath=/opt/brave-bin/brave"
      ],
      "enabled": true,
      "timeout": 60000
    },
    "lightpanda": {
      "type": "local",
      "command": [
        "lightpanda",
        "mcp"
      ],
      "enabled": true,
      "timeout": 60000,
      "description": "Lightpanda headless browser — быстрый MCP скрапинг"
    }
  },
  "agent": {
    "jarvis": {
      "tools": {
        "edit": false,
        "bash": false
      },
      "permission": {
        "edit": {
          "*": "deny"
        },
        "bash": {
          "*": "deny"
        },
        "websearch": "deny",
        "webfetch": "deny",
        "searxng_*": "deny",
        "crawl4ai_*": "deny",
        "deepwiki_*": "deny",
        "context7_*": "deny",
        "exa_*": "deny",
        "web-research_*": "deny",
        "youtube-transcript_*": "deny",
        "lightpanda_*": "deny"
      }
    },
    "title": {
      "model": "opencode/big-pickle"
    },
    "general": {
      "permission": {
        "edit": {
          "**/memory/**": "deny",
          "*": "allow"
        },
        "bash": {
          "*grep*": "deny",
          "*find*": "deny",
          "*npx*": "deny",
          "*npm*": "deny",
          "*sqlite*": "ask",
          "*": "allow"
        },
        "websearch": "allow",
        "webfetch": "allow",
        "skill": {
          "agent-delegation": "deny",
          "jarvis-cycles": "deny",
          "context-mgmt": "deny",
          "how_use_memory": "deny"
        }
      },
      "tools": {
        "glob": false,
        "grep": false,
        "sequential-thinking_*": true,
        "searxng_*": true,
        "deepwiki_*": true,
        "context7_*": true,
        "exa_*": true,
        "web-research_*": true,
        "crawl4ai_*": true,
        "youtube-transcript_*": true,
        "lightpanda_*": true
      }
    },
    "explore": {
      "disable": true
    }
  },
  "lsp": {},
  "plugin": [
    "opencode-intellisearch",
    "@tarquinen/opencode-dcp@3.1.13",
    "opencode-agent-memory"
  ],
  "compaction": {
    "auto": false,
    "prune": false
  },
  "tool_output": {
    "max_lines": 5000,
    "max_bytes": 204800
  },
  "experimental": {
    "mcp_timeout": 120000
  }
}
